<?php
if (!defined('ABSPATH')) exit;
/** Read-only, bounded completeness audit. No network requests. */
final class SDP_Missing {
    const MAX=100;
    public static function boot(){add_action('admin_menu',[__CLASS__,'menu'],30);add_action('admin_post_sdp_missing',[__CLASS__,'action']);}
    public static function menu(){add_submenu_page('sdp-directory','Kelengkapan Data','Kelengkapan Data','manage_options','sdp-missing',[__CLASS__,'page']);}
    public static function filters($raw){return SDP_Engine::filters($raw);}
    public static function blank($d,$k){return !isset($d[$k])||$d[$k]==='';}
    public static function inspect($row,$now){
        $d=json_decode($row['payload']??'',true);$id=$row['npsn']??null;
        if(!SDP_Engine::valid_npsn($id)||!is_array($d)||($d['npsn']??null)!==$id||!is_string($d['nama']??null))return new WP_Error('payload','Payload/identitas tidak valid.');
        if(SDP_SEO::demo($d))return null;
        $missing=[];$review=[];$groups=[];$reference=[];$website=[];
        foreach(SDP_Directory::fields() as $section=>$fields){$groups[$section]=0;foreach($fields as $k=>$label){if(SDP_SEO::present($d,$k)){$groups[$section]++;continue;}$missing[]=$k;if(!self::blank($d,$k)){$review[]=$k;continue;}if(in_array($k,SDP_Engine::FIELDS,true))$reference[]=$k;if(in_array($k,SDP_Website::FIELDS,true))$website[]=$k;}}
        $date=$row['updated_at']??'';$dt=is_string($date)?DateTimeImmutable::createFromFormat('!Y-m-d H:i:s',$date,new DateTimeZone('UTC')):false;
        $age=$dt&&$dt->format('Y-m-d H:i:s')===$date&&$dt->getTimestamp()<=$now?(int)floor(($now-$dt->getTimestamp())/86400):null;
        $recommend=[];if($reference)$recommend[]='Referensi Data Pendidikan';if(array_intersect($missing,['jumlah_siswa','siswa_laki_laki','siswa_perempuan','jumlah_guru','jumlah_tendik','guru_sertifikasi','jumlah_rombel','tahun_data']))$recommend[]='Dataset statistik resmi';if(array_intersect($missing,['akreditasi','tahun_akreditasi','nomor_sk_akreditasi','sertifikat_url']))$recommend[]='BAN-PDM / dataset akreditasi';if($website)$recommend[]=SDP_SEO::present($d,'website')?'Website resmi sekolah (tinjau)':'Verifikasi website resmi dahulu';if($review)$recommend[]='Tinjau nilai placeholder secara manual';if(!$recommend&&$missing)$recommend[]='Operator / dataset tambahan terverifikasi';
        $total=count(SDP_Directory::labels());return ['npsn'=>$id,'nama'=>$d['nama'],'jenjang'=>(string)($row['jenjang']??''),'kabupaten'=>(string)($row['kabupaten']??''),'kecamatan'=>(string)($row['kecamatan']??''),'missing'=>$missing,'review'=>$review,'groups'=>$groups,'reference'=>$reference,'website'=>$website,'filled'=>$total-count($missing),'score'=>(int)round(100*($total-count($missing))/$total),'age'=>$age,'recommend'=>$recommend,'relevant'=>SDP_Intelligence::completeness($d)];
    }
    public static function report($f,$now=null){
        global $wpdb;$now=$now??time();$t=SDP_Directory::table();$sql="SELECT s.npsn,s.nama,s.jenjang,s.kabupaten,s.kecamatan,s.payload,s.updated_at FROM $t s JOIN {$wpdb->posts} p ON p.ID=s.post_id WHERE p.post_type=%s AND p.post_status IN ('publish','draft','pending') AND p.post_password='' AND s.npsn NOT LIKE %s AND s.npsn NOT LIKE %s AND s.npsn NOT LIKE %s";$args=[SDP_Directory::TYPE,'DEMO%','SIMU%','TEST%'];
        foreach(['provinsi','kabupaten','kecamatan','jenjang'] as $k)if($f[$k]!==''){$sql.=" AND s.$k=%s";$args[]=$f[$k];}if($f['after']!==''){$sql.=' AND s.npsn>%s';$args[]=$f['after'];}$sql.=' ORDER BY s.npsn LIMIT %d';$args[]=$f['limit']+1;
        $raw=$wpdb->get_results($wpdb->prepare($sql,$args),ARRAY_A);if(!is_array($raw)||!empty($wpdb->last_error))return new WP_Error('database','Gagal membaca database sekolah.');
        $more=count($raw)>$f['limit'];$raw=array_slice($raw,0,$f['limit']);$next=$more?end($raw)['npsn']:'';if($next!==''&&!SDP_Engine::valid_npsn($next))return new WP_Error('identity','Cursor tidak valid. Periksa indeks.');
        $rows=[];$invalid=0;$demo=0;$stale=0;$unknown=0;$counts=array_fill_keys(array_keys(SDP_Directory::labels()),0);$groups=array_fill_keys(array_keys(SDP_Directory::fields()),0);
        foreach($raw as $r){$a=self::inspect($r,$now);if(is_wp_error($a)){$invalid++;continue;}if($a===null){$demo++;continue;}$rows[]=$a;foreach($a['missing'] as $k)$counts[$k]++;foreach($a['groups'] as $k=>$n)$groups[$k]+=$n;if($a['age']===null)$unknown++;elseif($a['age']>=180)$stale++;}
        usort($rows,static fn($a,$b)=>($a['filled']<=>$b['filled'])?:strcmp($a['npsn'],$b['npsn']));
        return ['filters'=>$f,'rows'=>$rows,'next'=>$next,'scanned'=>count($raw),'invalid'=>$invalid,'demo'=>$demo,'stale'=>$stale,'unknown'=>$unknown,'counts'=>$counts,'groups'=>$groups];
    }
    public static function engine_preview($report){$rows=[];foreach($report['rows'] as $r)if($r['reference'])$rows[]=array_intersect_key($r,array_flip(['npsn','nama','jenjang','kabupaten','kecamatan']));if(!$rows)return new WP_Error('empty','Tidak ada kolom kosong yang cocok untuk Mesin Pengayaan.');return ['filters'=>$report['filters'],'rows'=>$rows,'next'=>$report['next']];}
    public static function csv_cell($v){$s=(string)$v;return preg_match('/^[\s\x00-\x1f]*[=+\-@]|^[\x00-\x1f]/u',$s)?"'".$s:$s;}
    public static function csv($stream,$report){fputcsv($stream,['npsn','nama','jenjang','kabupaten','kecamatan','terisi','persen_68_atribut','umur_perubahan_lokal_hari','atribut_kurang','placeholder_tinjau','rekomendasi'],',','"','');foreach($report['rows'] as $r){$cells=[$r['npsn'],$r['nama'],$r['jenjang'],$r['kabupaten'],$r['kecamatan'],$r['filled'],$r['score'],$r['age']??'',implode('; ',$r['missing']),implode('; ',$r['review']),implode('; ',$r['recommend'])];fputcsv($stream,array_map([__CLASS__,'csv_cell'],$cells),',','"','');}}
    public static function action(){
        if(!current_user_can('manage_options'))wp_die('Akses ditolak.');check_admin_referer('sdp_missing');$f=self::filters(wp_unslash($_POST['filter']??[]));if(is_wp_error($f))wp_die(esc_html($f->get_error_message()));$p=self::report($f);if(is_wp_error($p))wp_die(esc_html($p->get_error_message()));$op=$_POST['op']??'';
        if($op==='csv'){nocache_headers();header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="sdp-kelengkapan.csv"');$fp=fopen('php://output','w');fwrite($fp,"\xEF\xBB\xBF");self::csv($fp,$p);fclose($fp);exit;}
        if($op==='engine'){$v=self::engine_preview($p);if(is_wp_error($v))wp_die(esc_html($v->get_error_message()));$key='sdp60_preview_'.get_current_user_id();if(!set_transient($key,$v,600))wp_die('Gagal menyimpan pratinjau.');wp_safe_redirect(admin_url('admin.php?page=sdp-engine'));exit;}wp_die('Operasi tidak dikenal.');
    }
    private static function hidden($f){foreach($f as $k=>$v)echo '<input type="hidden" name="filter['.esc_attr($k).']" value="'.esc_attr($v).'">';}
    public static function page(){
        if(!current_user_can('manage_options'))return;$raw=wp_unslash($_GET['filter']??[]);$f=self::filters($raw);$input=is_array($raw)?$raw:[];echo '<div class="wrap"><h1>Kelengkapan Data — v6.2</h1><p>Pemeriksaan lokal tanpa akses eksternal. Pilih provinsi dan filter opsional (nama persis di indeks). Statistik hanya untuk batch yang diperiksa, bukan seluruh wilayah. Profil draf/pending/terbit tanpa password disertakan; data fiktif, privat, dan sampah dikecualikan.</p><form method="get" action="'.esc_url(admin_url('admin.php')).'"><input type="hidden" name="page" value="sdp-missing">';
        foreach(['provinsi'=>'Provinsi','kabupaten'=>'Kabupaten / kota','kecamatan'=>'Kecamatan','after'=>'Mulai setelah NPSN'] as $k=>$label){$v=$input[$k]??'';echo '<p><label>'.esc_html($label).' <input name="filter['.esc_attr($k).']" value="'.esc_attr(is_scalar($v)?(string)$v:'').'" '.($k==='provinsi'?'required':'').'></label></p>';}
        echo '<p><label>Jenjang <select name="filter[jenjang]"><option value="">Semua</option>';foreach(SDP_Directory::levels() as $v)echo '<option value="'.esc_attr($v).'" '.selected($input['jenjang']??'',$v,false).'>'.esc_html($v).'</option>';echo '</select></label></p><p><label>Batas batch <input type="number" name="filter[limit]" min="1" max="100" value="'.esc_attr(is_scalar($input['limit']??100)?($input['limit']??100):100).'"></label></p><button class="button button-primary">Periksa kelengkapan</button></form>';
        if(is_wp_error($f)){if($raw)echo '<p>'.esc_html($f->get_error_message()).'</p>';echo '</div>';return;}$p=self::report($f);if(is_wp_error($p)){echo '<p>'.esc_html($p->get_error_message()).'</p></div>';return;}$n=count($p['rows']);echo '<h2>Ringkasan batch</h2><p>Dipindai: '.(int)$p['scanned'].' · Valid: '.$n.' · Payload bermasalah: '.(int)$p['invalid'].' · Fiktif: '.(int)$p['demo'].' · Tidak diperbarui lokal ≥180 hari: '.(int)$p['stale'].' · Waktu perubahan tidak diketahui: '.(int)$p['unknown'].'</p><p>Skor mentah 68 atribut bukan kualitas sekolah. Beberapa atribut (misalnya jurusan SMK) mungkin tidak relevan. Nol sah dihitung terisi; placeholder dihitung kurang tetapi perlu ditinjau manual. Umur perubahan lokal bukan umur fakta dari sumber.</p>';
        if($n){echo '<h3>Kelengkapan per kategori</h3><table class="widefat striped"><thead><tr><th>Kategori</th><th>Terisi / total slot</th><th>Persen</th></tr></thead><tbody>';foreach(SDP_Directory::fields() as $k=>$fields){$den=$n*count($fields);$num=$p['groups'][$k];echo '<tr><td>'.esc_html($k).'</td><td>'.$num.' / '.$den.'</td><td>'.round(100*$num/$den,1).'%</td></tr>';}echo '</tbody></table><details><summary>Rincian seluruh 68 atribut</summary><table class="widefat striped"><thead><tr><th>Atribut</th><th>Kurang</th><th>Terisi</th></tr></thead><tbody>';foreach(SDP_Directory::labels() as $k=>$label)echo '<tr><td>'.esc_html($label).'</td><td>'.$p['counts'][$k].'</td><td>'.($n-$p['counts'][$k]).'</td></tr>';echo '</tbody></table></details><h3>Prioritas dalam batch (skor terendah dahulu)</h3><table class="widefat striped"><thead><tr><th>Sekolah</th><th>Terisi</th><th>Kurang</th><th>Sumber yang disarankan</th><th>Umur lokal</th></tr></thead><tbody>';foreach($p['rows'] as $r){$url=add_query_arg('npsn',$r['npsn'],admin_url('admin.php?page=sdp-edit'));echo '<tr><td><a href="'.esc_url($url).'">'.esc_html($r['nama']).'</a><br>'.esc_html($r['npsn'].' · '.$r['jenjang']).'</td><td>'.$r['filled'].'/68 ('.$r['score'].'%)<br>Relevan: '.(int)$r['relevant']['score'].'% <a href="'.esc_url(add_query_arg('npsn',$r['npsn'],admin_url('admin.php?page=sdp-intelligence'))).'">Validasi</a></td><td><details><summary>'.count($r['missing']).' atribut</summary>'.esc_html(implode(', ',array_intersect_key(SDP_Directory::labels(),array_flip($r['missing'])))).'</details></td><td>'.esc_html(implode('; ',$r['recommend']));if($r['website'])echo '<br><a href="'.esc_url(add_query_arg('npsn',$r['npsn'],admin_url('admin.php?page=sdp-website'))).'">Tinjau website</a>';else echo '<br><a href="'.esc_url(add_query_arg('npsn',$r['npsn'],admin_url('admin.php?page=sdp-discovery'))).'">Temukan website</a>';echo '</td><td>'.esc_html($r['age']===null?'Tidak diketahui':$r['age'].' hari').'</td></tr>';}echo '</tbody></table>';}
        echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="sdp_missing">';wp_nonce_field('sdp_missing');self::hidden($f);echo '<p><button class="button" name="op" value="csv">Ekspor batch CSV</button> ';if(!is_wp_error(self::engine_preview($p)))echo '<button class="button" name="op" value="engine">Kirim kandidat ke pratinjau Mesin Pengayaan</button>';echo '</p></form><p>Ekspor dan pratinjau membaca ulang batch. Tidak memulai kampanye atau mengubah profil.</p>';if($p['next']!==''){$next=$f;$next['after']=$p['next'];echo '<form method="get" action="'.esc_url(admin_url('admin.php')).'"><input type="hidden" name="page" value="sdp-missing">';self::hidden($next);echo '<button class="button">Batch berikutnya</button></form>';}echo '</div>';
    }
}
